package com.fireplatform;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fireplatform.shared.*;
import com.fireplatform.simcard.*;
import java.sql.ResultSet;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.jdbc.core.JdbcTemplate;
import static com.fireplatform.simcard.SimCardModels.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;

class SimCardProjectionTest {
    static final String ID="123e4567-e89b-12d3-a456-426614174000",CHANGE="223e4567-e89b-12d3-a456-426614174000",STAMP="2026-01-02T03:04:05.123456Z";
    final ObjectMapper json=new ObjectMapper().setPropertyNamingStrategy(PropertyNamingStrategies.SNAKE_CASE).enable(DeserializationFeature.USE_BIG_INTEGER_FOR_INTS).enable(DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);
    Card card(){return new Card(ID,"tenant-a","0000Case","","REMOVABLE","UNKNOWN","UNKNOWN","UNKNOWN","UNKNOWN",null,null,"","MANUAL",0,STAMP);}
    ObjectNode node(){return json.valueToTree(card());}
    void unconfirmed(org.assertj.core.api.ThrowableAssert.ThrowingCallable code){assertThatThrownBy(code).isInstanceOfSatisfying(ApiError.class,e->{assertThat(e.status).isEqualTo(503);assertThat(e.code).isEqualTo("SIM_CARD_READ_UNCONFIRMED");assertThat(e.getMessage()).doesNotContain("SECRET");});}
    @Test void publicCard15AndHistoryFlat17NeverIncludeActorOrNestedCard()throws Exception{var card=json.readTree(json.writeValueAsBytes(card()));assertThat(card.size()).isEqualTo(15);assertThat(card.get("expires_on").isNull()).isTrue();assertThat(card.get("evidence_at").isNull()).isTrue();var history=json.readTree(json.writeValueAsBytes(History.of(card(),CHANGE,"CREATE")));assertThat(history.size()).isEqualTo(17);assertThat(history.has("card")).isFalse();assertThat(history.get("id").asText()).isEqualTo(ID);assertThat(history.get("change_id").asText()).isEqualTo(CHANGE);assertThat(history.toString()).doesNotContain("actor","username");assertThat(json.valueToTree(new CardPage(List.of(card()),1,1,20)).size()).isEqualTo(4);assertThat(json.valueToTree(new ChangesPage(card(),List.of(History.of(card(),CHANGE,"CREATE")),1,1,20)).size()).isEqualTo(5);}
    @Test void safeReceiptRoundTripsWithoutInventingUnknownEvidence()throws Exception{assertThat(json.readValue(json.writeValueAsBytes(card()),Card.class)).isEqualTo(card());assertThat(SimCardProjection.stored(node())).isEqualTo(card());}
    @Test void storedShapeNeverDropsUnknownKeysOrMissingNullableKeys(){var extra=node();extra.put("SECRET",true);unconfirmed(()->SimCardProjection.stored(extra));for(String key:List.of("id","tenant_id","expires_on","evidence_at","source_note","revision")){var n=node();n.remove(key);unconfirmed(()->SimCardProjection.stored(n));}unconfirmed(()->SimCardProjection.stored(json.getNodeFactory().nullNode()));unconfirmed(()->SimCardProjection.stored(json.createArrayNode()));}
    @Test void storedScalarsAndNearIntegersCannotCoerce(){for(String key:List.of("id","tenant_id","iccid","carrier_name","source_note","information_source","recorded_at")){var n=node();n.put(key,1);unconfirmed(()->SimCardProjection.stored(n));n.putNull(key);unconfirmed(()->SimCardProjection.stored(n));}for(JsonNode value:List.of(json.getNodeFactory().textNode("0"),json.getNodeFactory().numberNode(new java.math.BigDecimal("0.00000000000000000001")),json.getNodeFactory().numberNode(SimCardInputs.MAX_SAFE+1),json.getNodeFactory().numberNode(-1))){var n=node();n.set("revision",value);unconfirmed(()->SimCardProjection.stored(n));}}
    @Test void sourceMustBeCanonicalRatherThanTrimmedDefaultedOrExpanded(){for(var entry:Map.of("id",ID.toUpperCase(Locale.ROOT),"iccid"," noncanonical ","source_note"," trailing ","installation_form","EMBEDDED","information_source","API","replaceability","UNKNOWN_FUTURE","management_party","VENDOR","fee_responsibility","","reported_operator_status","TRUE").entrySet()){var n=node();n.put(entry.getKey(),entry.getValue());unconfirmed(()->SimCardProjection.stored(n));}unconfirmed(()->SimCardProjection.valid(card(),"tenant-b"));}
    @Test void receiptDatesAndTimeMustBeRealCanonicalFixedMicroseconds(){for(String key:List.of("recorded_at","evidence_at"))for(String value:List.of("2026-01-02T03:04:05Z","2026-01-02T03:04:05.1Z","2026-01-02T03:04:05.1234567Z","2026-01-02T03:04:05.123456+00:00","0000-01-01T00:00:00.000000Z")){var n=node();n.put(key,value);unconfirmed(()->SimCardProjection.stored(n));}var date=node();date.put("expires_on","2026-02-30");unconfirmed(()->SimCardProjection.stored(date));}
    @Test void receiptParserRejectsDuplicateKeysTrailingRootAndNull()throws Exception{String valid=json.writeValueAsString(card());for(String raw:List.of(valid+" {}",valid.substring(0,valid.length()-1)+",\"revision\":0}","null","[]","{"))assertThatThrownBy(()->json.readValue(raw,Card.class)).isInstanceOf(Exception.class);}
    @Test void jdbcTimestampNeverLosesSubMillisecondEvidenceOrAcceptsUnsafeYears(){assertThat(SimCardProjection.instant(OffsetDateTime.parse(STAMP))).isEqualTo(STAMP);assertThat(SimCardProjection.instant(OffsetDateTime.parse("2026-01-02T04:04:05.123456+01:00"))).isEqualTo(STAMP);unconfirmed(()->SimCardProjection.instant(null));unconfirmed(()->SimCardProjection.instant(OffsetDateTime.parse("2026-01-02T03:04:05.123456789Z")));unconfirmed(()->SimCardProjection.instant(OffsetDateTime.of(9999,12,31,23,59,59,0,ZoneOffset.ofHours(-1))));}
    @Test void totalsAndRevisionsRejectJdbcNullNegativeAndUnsafeIntegers()throws Exception{var rs=mock(ResultSet.class);when(rs.getLong(1)).thenReturn(0L);when(rs.wasNull()).thenReturn(true);unconfirmed(()->SimCardProjection.total(rs));for(long value:new long[]{-1,SimCardInputs.MAX_SAFE+1})unconfirmed(()->SimCardProjection.safe(value));assertThat(SimCardProjection.safe(SimCardInputs.MAX_SAFE)).isEqualTo(SimCardInputs.MAX_SAFE);}
    @Test void badCentralSizeIs503EvenWhenExplicitOneCouldHideIt(){for(long value:new long[]{0,4,101,Long.MAX_VALUE})for(Integer requested:Arrays.asList(null,1)){var jdbc=mock(JdbcTemplate.class);var sizes=mock(PageSizePolicy.class);when(sizes.defaultPageSize()).thenReturn(value);var query=new SimCardQueries(jdbc,sizes,mock(TransactionRequirements.class));unconfirmed(()->query.cards("tenant-a",1,requested,SimCardFilter.parse(null)));assertThat(mockingDetails(jdbc).getInvocations()).isEmpty();}}
    @Test void queryColumnsAreClosedAndDoNotReadUsersDevicesOrSecrets(){assertThat(SimCardProjection.CARD_COLUMNS).startsWith("c.id,c.tenant_id").doesNotContain("*","actor","app_users","devices","password");assertThat(SimCardProjection.HISTORY_COLUMNS).startsWith("h.card_id AS id").contains("h.id AS change_id","h.operation").doesNotContain("actor","username","password");}
    @Test void unrelatedSqlstatesOrUnstructuredMessagesNeverBecomeIccidConflict(){for(Throwable failure:List.of(new java.sql.SQLException("uq_sim_cards_tenant_iccid","23505"),new java.sql.SQLException("other unique","23505"),new java.sql.SQLException("foreign key","23503"),new IllegalStateException("SECRET")))assertThat(SimCardConflicts.iccid(failure)).isFalse();}
}
